package com.example.starter.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 刷新令牌业务配置。
 *
 * @param signingKey 合成 HMAC 签名密钥，仅用于本地/测试的确定性令牌派生
 * @param ttlSeconds 刷新令牌有效期，单位秒
 */
@ConfigurationProperties(prefix = "refresh-token")
public record RefreshTokenProperties(
        String signingKey,
        long ttlSeconds
) {
}

package com.example.starter.config;

import java.time.Clock;
import java.time.ZoneOffset;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 刷新令牌模块装配：启用配置属性并提供可控的 UTC 时钟（测试可替换）。
 */
@Configuration
@EnableConfigurationProperties(RefreshTokenProperties.class)
public class RefreshTokenConfig {

    /**
     * 业务统一使用的时钟，默认 UTC 系统时钟；测试中可替换为固定/可调时钟。
     */
    @Bean
    public Clock applicationClock() {
        return Clock.system(ZoneOffset.UTC);
    }
}

package com.example.starter.domain;

/**
 * 令牌族状态。
 *
 * <p>ACTIVE：族内当前令牌可正常轮换；REVOKED：族已撤销（登出或检测到重放），
 * 族内任何令牌都不得再轮换。
 */
public enum FamilyStatus {
    ACTIVE,
    REVOKED
}

package com.example.starter.domain;

/**
 * 单个刷新令牌状态。
 *
 * <p>ACTIVE：未消费且在有效期内；CONSUMED：已被合法轮换消费；
 * EXPIRED：已到期失效（now &gt;= expiresAt）；REVOKED：随族撤销。
 */
public enum TokenStatus {
    ACTIVE,
    CONSUMED,
    EXPIRED,
    REVOKED
}

package com.example.starter.domain;

/**
 * 安全事件类型。当前仅记录重放检测事件 REPLAY_DETECTED。
 */
public enum SecurityEventType {
    REPLAY_DETECTED
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 安全事件持久化对象。每个族至多有一条 REPLAY_DETECTED 事件（数据库唯一约束保证）。
 *
 * @param id                 自增主键
 * @param familyId           所属令牌族标识
 * @param eventType          事件类型
 * @param requestId          触发事件的请求键；可能为 {@code null}
 * @param tokenHash          触发事件的令牌 SHA-256
 * @param requestFingerprint 请求指纹（族标识+请求键+客户端+令牌哈希的 SHA-256）
 * @param detail             事件补充说明
 * @param createdAt          事件时间（epoch 毫秒，UTC）
 */
public record SecurityEventEntity(
        Long id,
        String familyId,
        SecurityEventType eventType,
        String requestId,
        String tokenHash,
        String requestFingerprint,
        String detail,
        Instant createdAt
) {
}

