package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 令牌轮换请求。
 *
 * @param requestId    请求键（客户端生成的幂等键）
 * @param refreshToken 当前刷新令牌明文
 * @param clientId     客户端标识
 */
public record RotateRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 512) String refreshToken,
        @NotBlank @Size(max = 128) String clientId
) {
}

package com.example.starter.api;

import java.time.Instant;

/**
 * 令牌轮换响应。
 *
 * @param familyId     令牌族标识
 * @param refreshToken 新的子刷新令牌明文；安全重试命中首次结果时返回首次子令牌
 * @param expiresAt    子令牌到期时间（UTC）
 * @param requestId    请求键
 * @param replayed     是否为安全重试（同键同参重放）返回的首次结果
 */
public record RotateResponse(
        String familyId,
        String refreshToken,
        Instant expiresAt,
        String requestId,
        boolean replayed
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 登出请求：撤销整个令牌族。
 *
 * @param familyId 令牌族标识
 * @param clientId 客户端标识（需与族绑定的客户端一致）
 */
public record LogoutRequest(
        @NotBlank @Size(max = 128) String familyId,
        @NotBlank @Size(max = 128) String clientId
) {
}

package com.example.starter.api;

import java.time.Instant;

/**
 * 令牌族状态视图。
 *
 * @param familyId         族标识
 * @param userId           合成用户标识
 * @param clientId         客户端标识
 * @param status           族状态（ACTIVE/REVOKED）
 * @param revokeReason     撤销原因（REPLAY_DETECTED/LOGOUT）；未撤销为 {@code null}
 * @param createdAt        创建时间（UTC）
 * @param revokedAt        撤销时间（UTC）；未撤销为 {@code null}
 * @param tokenCount       族内令牌总数
 * @param activeTokenCount 仍为 ACTIVE 状态的令牌数
 */
public record FamilyStatusResponse(
        String familyId,
        String userId,
        String clientId,
        String status,
        String revokeReason,
        Instant createdAt,
        Instant revokedAt,
        int tokenCount,
        int activeTokenCount
) {
}

package com.example.starter.api;

import java.time.Instant;

/**
 * 安全事件视图。
 *
 * @param id                 事件标识
 * @param familyId           所属令牌族
 * @param eventType          事件类型（当前为 REPLAY_DETECTED）
 * @param requestId          触发事件的请求键
 * @param requestFingerprint 请求指纹
 * @param detail             事件补充说明
 * @param createdAt          事件时间（UTC）
 */
public record SecurityEventResponse(
        Long id,
        String familyId,
        String eventType,
        String requestId,
        String requestFingerprint,
        String detail,
        Instant createdAt
) {
}

package com.example.starter.api;

import java.time.Instant;

/**
 * 统一错误响应体。
 *
 * @param status    HTTP 状态码
 * @param error     错误码
 * @param message   错误说明
 * @param timestamp 错误产生时间（UTC）
 */
public record ErrorResponse(
        int status,
        String error,
        String message,
        Instant timestamp
) {
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类：携带 HTTP 状态与稳定错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/** 请求资源不存在（如未知令牌族）。 */
public class NotFoundException extends ApiException {
    public NotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/** 令牌无效（不存在、格式非法或无法识别）。 */
public class InvalidTokenException extends ApiException {
    public InvalidTokenException(String message) {
        super(HttpStatus.UNAUTHORIZED, "INVALID_TOKEN", message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/** 令牌已到期：now &gt;= expiresAt。 */
public class TokenExpiredException extends ApiException {
    public TokenExpiredException(String message) {
        super(HttpStatus.UNAUTHORIZED, "TOKEN_EXPIRED", message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/** 令牌族已撤销（登出或重放检测），族内任何令牌不得再轮换。 */
public class FamilyRevokedException extends ApiException {
    public FamilyRevokedException(String message) {
        super(HttpStatus.FORBIDDEN, "FAMILY_REVOKED", message);
    }
}

package com.example.starter.service;

import org.springframework.http.HttpStatus;

/** 请求冲突：同请求键但令牌或客户端不同，返回 409。 */
public class RequestConflictException extends ApiException {
    public RequestConflictException(String message) {
        super(HttpStatus.CONFLICT, "REQUEST_CONFLICT", message);
    }
}

